PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT,
  email TEXT UNIQUE,
  phone TEXT UNIQUE,
  password_hash TEXT,
  is_admin INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, referral_code TEXT, referred_by INTEGER);
CREATE TABLE password_resets (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  token TEXT UNIQUE,
  expires_at TEXT,
  used INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE kitchen_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1), -- single-row settings table (id=1)
  kitchen_open_time TEXT DEFAULT '08:00',
  kitchen_close_time TEXT DEFAULT '22:00',
  global_cutoff_minutes INTEGER DEFAULT 15,
  prep_time_default_minutes INTEGER DEFAULT 20,
  next_day_cutoff_time TEXT DEFAULT '23:30',
  allow_subscriptions INTEGER DEFAULT 1,
  timezone TEXT DEFAULT 'Asia/Kolkata',
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE shipping_zones (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT,
  states TEXT, -- JSON text array of states: '["Rajasthan","Delhi"]'
  base_first_500g REAL DEFAULT 0,
  extra_500g REAL DEFAULT 0,
  oda INTEGER DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE coupons (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  code TEXT UNIQUE,
  discount_type TEXT, -- 'flat' or 'percent'
  discount_value REAL,
  min_order_amount REAL DEFAULT 0,
  valid_from TEXT,
  valid_to TEXT,
  is_active INTEGER DEFAULT 1,
  user_specific INTEGER DEFAULT 0,
  allowed_user_ids TEXT, -- JSON array of user IDs
  item_specific INTEGER DEFAULT 0,
  allowed_variant_ids TEXT, -- JSON array of variant IDs
  usage_limit INTEGER,
  times_used INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE order_items (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER,
  variant_id INTEGER,
  product_id INTEGER,
  name TEXT,
  variant_name TEXT,
  qty INTEGER,
  price_per_unit REAL,
  total_price REAL,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE
);
CREATE TABLE addresses (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER,
  name TEXT,
  phone TEXT,
  house TEXT,
  street TEXT,
  area TEXT,
  city TEXT,
  state TEXT,
  pincode TEXT,
  latitude REAL,
  longitude REAL,
  is_default INTEGER DEFAULT 0,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE delivery_slots (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,               -- Lunch / Dinner / Breakfast
  order_start_time TEXT NOT NULL,   -- HH:MM
  order_end_time TEXT NOT NULL,     -- HH:MM
  delivery_start_time TEXT NOT NULL,
  delivery_end_time TEXT NOT NULL,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, cutoff_minutes INTEGER DEFAULT 30);
CREATE TABLE categories (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  slug TEXT UNIQUE,
  description TEXT,
  shipping_type TEXT DEFAULT 'local', 
  is_local_only INTEGER DEFAULT 1,
  subscription_allowed INTEGER DEFAULT 0,
  slot_wise INTEGER DEFAULT 0,        -- From Alter
  prep_time_minutes INTEGER DEFAULT 20,
  delivery_time_minutes INTEGER DEFAULT 20,
  cutoff_minutes INTEGER DEFAULT 0,
  next_day_delivery INTEGER DEFAULT 0,
  slot_start TEXT,
  slot_end TEXT,
  min_order_amount REAL DEFAULT 0,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
, image_path TEXT);
CREATE TABLE category_slots (
  category_id INTEGER NOT NULL,
  slot_id INTEGER NOT NULL,
  PRIMARY KEY (category_id, slot_id),
  FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE,
  FOREIGN KEY (slot_id) REFERENCES delivery_slots(id) ON DELETE CASCADE
);
CREATE TABLE products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  sku TEXT UNIQUE,
  name TEXT NOT NULL,
  slug TEXT UNIQUE,
  description TEXT,
  category_id INTEGER,
  is_active INTEGER DEFAULT 1,
  is_featured INTEGER DEFAULT 0,
  image_path TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL
);
CREATE TABLE product_variants (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  product_id INTEGER NOT NULL,
  variant_name TEXT, 
  description TEXT DEFAULT '',       -- From Alter
  price REAL DEFAULT 0,
  old_price REAL,
  is_default INTEGER DEFAULT 0,      -- From Alter
  ship_type TEXT DEFAULT 'local', 
  weight_grams INTEGER DEFAULT 0,
  length_cm REAL DEFAULT 0,
  width_cm REAL DEFAULT 0,
  height_cm REAL DEFAULT 0,
  stock INTEGER DEFAULT 0,
  max_per_order INTEGER DEFAULT 0,
  min_order INTEGER DEFAULT 1,
  slot_type TEXT DEFAULT 'none', 
  slot_cutoff_minutes INTEGER DEFAULT 0,
  next_day_delivery INTEGER DEFAULT 0,
  available_from_time TEXT,
  available_to_time TEXT,
  is_active INTEGER DEFAULT 1,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE
);
CREATE TABLE carts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER UNIQUE,            -- Added Unique Constraint
  cart_key TEXT, 
  cart_json TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_no TEXT UNIQUE,
  user_id INTEGER,
  cart_snapshot TEXT,
  address_snapshot TEXT,
  customer_name TEXT,
  customer_email TEXT,
  customer_phone TEXT,
  amount_subtotal REAL,
  shipping_amount REAL,
  discount_amount REAL,
  tax_amount REAL DEFAULT 0,
  amount_total REAL,
  razorpay_order_id TEXT,
  razorpay_payment_id TEXT,
  razorpay_payment_status TEXT,
  payment_status TEXT DEFAULT 'pending', -- pending, paid, failed, refunded
  order_status TEXT DEFAULT 'created', -- created, confirmed, preparing, out_for_delivery, delivered, cancelled
  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE TABLE order_tracking (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  order_id INTEGER,
  status TEXT,
  note TEXT,
  created_at TEXT DEFAULT (datetime('now')),
  FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE
);
CREATE TABLE pincode_master (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    pincode TEXT NOT NULL,
    city TEXT NOT NULL,
    state TEXT NOT NULL,
    area_name TEXT,
    latitude REAL,
    longitude REAL,
    service_tier INTEGER DEFAULT 2, 
    zone_id TEXT DEFAULT 'D', 
    local_shipping_fee REAL DEFAULT 0.00,
    min_order_free_delivery REAL DEFAULT 0.00,
    is_active INTEGER DEFAULT 1
);
CREATE TABLE product_reviews (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER NOT NULL,
    order_id INTEGER NOT NULL,
    variant_id INTEGER NOT NULL,
    product_id INTEGER NOT NULL,
    order_no TEXT NOT NULL,
    rating INTEGER NOT NULL CHECK (rating >= 1 AND rating <= 5),
    review_title TEXT,            -- OPTIONAL Phase 1
    review_text TEXT,             -- Provisioned for Phase 2
    is_anonymous INTEGER DEFAULT 0,  -- Provisioned
    images TEXT DEFAULT NULL,     -- JSON array provisioned
    helpful_votes INTEGER DEFAULT 0, -- Provisioned
    status TEXT DEFAULT 'active' CHECK (status IN ('active', 'pending', 'rejected')),
    created_at TEXT DEFAULT (datetime('now')),
    updated_at TEXT DEFAULT (datetime('now')),
    
    -- 🔥 FOREIGN KEYS
    FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,
    FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE CASCADE,
    FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE,
    
    -- 🔥 Business rules
    UNIQUE(user_id, order_id, variant_id)
);
CREATE TABLE geo_cache (
    cache_key TEXT PRIMARY KEY,
    result TEXT,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE mithora_feedback (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  
  visit_reason TEXT,
  found_required TEXT,
  pricing_feedback TEXT,
  checked_competitor TEXT,
  competitor_price TEXT,
  
  customer_name TEXT,
  customer_phone TEXT,
  
  source_page TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, additional_comment TEXT);
CREATE TABLE pin_reset_otps (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id INTEGER NOT NULL,
  email TEXT NOT NULL,
  otp_salt TEXT NOT NULL,
  otp_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  used INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (user_id) REFERENCES users(id)
);
CREATE TABLE signup_otps (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  phone TEXT NOT NULL,
  email TEXT NOT NULL,
  name TEXT NOT NULL,
  otp_salt TEXT NOT NULL,
  otp_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  attempts INTEGER NOT NULL DEFAULT 0,
  used INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE product_badges (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  display_text TEXT NOT NULL,

  icon TEXT,

  priority INTEGER NOT NULL DEFAULT 0,

  is_active INTEGER NOT NULL DEFAULT 1,

  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE product_badge_map (
  product_id INTEGER NOT NULL,
  badge_id INTEGER NOT NULL,

  PRIMARY KEY (
    product_id,
    badge_id
  ),

  FOREIGN KEY (product_id)
    REFERENCES products(id)
    ON DELETE CASCADE,

  FOREIGN KEY (badge_id)
    REFERENCES product_badges(id)
    ON DELETE CASCADE
);
CREATE TABLE product_tags (
  id INTEGER PRIMARY KEY AUTOINCREMENT,

  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,

  is_active INTEGER NOT NULL DEFAULT 1,

  created_at TEXT DEFAULT (datetime('now')),
  updated_at TEXT DEFAULT (datetime('now'))
);
CREATE TABLE product_tag_map (
  product_id INTEGER NOT NULL,
  tag_id INTEGER NOT NULL,

  PRIMARY KEY (
    product_id,
    tag_id
  ),

  FOREIGN KEY (product_id)
    REFERENCES products(id)
    ON DELETE CASCADE,

  FOREIGN KEY (tag_id)
    REFERENCES product_tags(id)
    ON DELETE CASCADE
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_pwreset_token ON password_resets(token);
CREATE INDEX idx_coupons_code ON coupons(code);
CREATE INDEX idx_order_items_order ON order_items(order_id);
CREATE INDEX idx_orders_user ON orders(user_id);
CREATE INDEX idx_orders_orderno ON orders(order_no);
CREATE INDEX idx_order_tracking_order ON order_tracking(order_id);
CREATE INDEX idx_users_phone ON users(phone);
CREATE INDEX idx_addresses_user ON addresses(user_id);
CREATE INDEX idx_addresses_pincode ON addresses(pincode);
CREATE INDEX idx_users_email ON users(email);
CREATE INDEX idx_products_category ON products(category_id);
CREATE INDEX idx_variants_product ON product_variants(product_id);
CREATE INDEX idx_orders_no ON orders(order_no);
CREATE INDEX idx_category_slots_cid ON category_slots (category_id);
CREATE INDEX idx_category_slots_category
ON category_slots (category_id);
CREATE INDEX idx_category_slots_slot
ON category_slots (slot_id);
CREATE UNIQUE INDEX idx_carts_user_id ON carts(user_id);
CREATE INDEX idx_pincode_lookup ON pincode_master (pincode);
CREATE UNIQUE INDEX idx_pincode_area_unique ON pincode_master (pincode, area_name);
CREATE INDEX idx_city_tier ON pincode_master (city, service_tier);
CREATE INDEX idx_reviews_product ON product_reviews(product_id);
CREATE INDEX idx_reviews_variant ON product_reviews(variant_id);
CREATE INDEX idx_reviews_user ON product_reviews(user_id);
CREATE INDEX idx_reviews_rating ON product_reviews(rating);
CREATE INDEX idx_reviews_helpful ON product_reviews(helpful_votes);
CREATE INDEX idx_reviews_status ON product_reviews(status);
CREATE INDEX idx_geo_cache_date ON geo_cache(created_at);
CREATE INDEX idx_geo_cache_key ON geo_cache(cache_key);
CREATE INDEX idx_pincode_master_active ON pincode_master(pincode, is_active);
CREATE INDEX idx_mithora_feedback_phone 
ON mithora_feedback(customer_phone);
CREATE INDEX idx_mithora_feedback_created 
ON mithora_feedback(created_at);
CREATE UNIQUE INDEX idx_users_referral_code 
ON users(referral_code);
CREATE INDEX idx_pin_reset_otps_email
ON pin_reset_otps(email);
CREATE INDEX idx_pin_reset_otps_user_id
ON pin_reset_otps(user_id);
CREATE INDEX idx_signup_otps_phone
ON signup_otps(phone);
CREATE INDEX idx_signup_otps_email
ON signup_otps(email);
CREATE INDEX idx_categories_active
ON categories(is_active);
CREATE INDEX idx_categories_slug
ON categories(slug);
CREATE TRIGGER trg_users_upd AFTER UPDATE ON users BEGIN
  UPDATE users SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_products_upd AFTER UPDATE ON products BEGIN
  UPDATE products SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_variants_upd AFTER UPDATE ON product_variants BEGIN
  UPDATE product_variants SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_categories_upd AFTER UPDATE ON categories BEGIN
  UPDATE categories SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE TRIGGER trg_orders_upd AFTER UPDATE ON orders BEGIN
  UPDATE orders SET updated_at = datetime('now') WHERE id = NEW.id;
END;
CREATE VIEW order_items_view AS
SELECT 
  o.id as order_id, o.order_no,
  json_extract(item.value, '$.name') as item_name,
  json_extract(item.value, '$.qty') as qty,
  json_extract(item.value, '$.price') as price
FROM orders o, json_each(o.cart_snapshot) as item;
